const simpleHash = (value) => {
  let hash = 5381;
  for (const character of value) {
    hash = ((hash << 5) + hash) ^ character.charCodeAt(0);
  }
  return (hash >>> 0).toString(16);
};

return items.map((item) => {
  const source = String(item.json.source ?? 'unknown').trim().toLowerCase();
  const contact = String(item.json.contact ?? '').trim();
  const rawText = String(item.json.message ?? '').trim();

  if (!contact || !rawText) {
    throw new Error('A lead must contain contact and message fields.');
  }

  const normalizedText = rawText.replace(/\s+/g, ' ');
  const deduplicationKey = `${contact.toLowerCase()}|${normalizedText.toLowerCase()}`;

  return {
    json: {
      lead_id: `lead_${Date.now()}_${Math.floor(Math.random() * 100000)}`,
      created_at: new Date().toISOString(),
      source,
      contact,
      telegram_chat_id: item.json.telegram_chat_id ? String(item.json.telegram_chat_id) : null,
      answers: item.json.answers ?? {},
      raw_text: rawText,
      normalized_text: normalizedText,
      message_hash: simpleHash(deduplicationKey),
      status: 'new'
    }
  };
});

return items.map((item) => ({
  json: {
    accepted: true,
    lead_id: item.json.lead_id,
    status: item.json.status
  }
}));
